const products=[['Classic White Shirt','👔',499],['Straight Fit Jeans','👖',699],['Everyday T-Shirt','👕',299],['Casual Blue Shirt','👔',549],['Relaxed Denim','👖',799],['Basic Black Tee','👕',349]];
document.querySelector('#products').innerHTML=products.map(([name,icon,price],i)=>`<article class="product"><div class="garment" aria-label="Illustration of ${name}">${icon}</div><h3>${name}</h3><div class="price">Rs. ${price}/-</div><label>Size <select id="size${i}" aria-label="Size for ${name}"><option>M</option><option>L</option><option>XL</option></select></label><button data-item="${i}">ENQUIRE NOW</button></article>`).join('');
document.querySelector('#products').addEventListener('click',e=>{const b=e.target.closest('[data-item]');if(!b)return;const i=Number(b.dataset.item);document.querySelector('#messageText').textContent=`${products[i][0]} — Size ${document.querySelector('#size'+i).value}. Online enquiries are coming soon. Please visit our store for current availability.`;document.querySelector('#message').showModal()});
document.querySelector('#motion').onclick=e=>{const paused=document.body.classList.toggle('paused');e.target.textContent=paused?'Resume lights':'Pause lights';e.target.setAttribute('aria-pressed',String(paused))};
